"""Build the clubs migration (table + data) from the UCR HighlanderLink export.

Usage (from the repo root):
    python3 supabase/scripts/build_clubs_migration.py "/path/to/UCR_clubs_complete_data" supabase/migrations/<file>.sql

The club data lives in the migration (not seed.sql) so `npx supabase db push`
loads it on the hosted project without re-inserting the class data.
"""
import csv
import sys
from pathlib import Path

NOT_LISTED = {"", "not publicly listed", "tba", "tbd"}

SCHEMA = """-- UCR clubs and student groups (HighlanderLink public directory, retrieved 2026-10-08).
-- Generated by supabase/scripts/build_clubs_migration.py.
--
-- Meeting times are free text exactly as each club reported them
-- (e.g. 'Tuesdays/Thursdays at 8pm', 'Varies with schedule'), so they are
-- stored as text, not structured times. Null = the club did not publish one.

create table public.clubs (
  id                integer primary key,      -- HighlanderLink organization ID
  name              text not null,
  organization_type text,                     -- Registered Student Organization, ...
  categories        text[],                   -- {'Academic/Professional','Service'}
  meeting_schedule  text,                     -- reported day/time, free text
  meeting_frequency text,                     -- Weekly, Every two weeks, Monthly, ...
  meeting_notes     text,                     -- meeting/practice lines from the description
  summary           text,
  description       text,
  email             text,
  website           text,
  instagram         text,
  profile_url       text
);

create index clubs_name_idx on public.clubs (name);

alter table public.clubs enable row level security;
create policy "Clubs are readable by everyone" on public.clubs for select using (true);

"""


def read(folder, name):
    with open(Path(folder) / name, encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


def lit(value):
    if isinstance(value, list):
        return "array[" + ",".join(lit(v) for v in value) + "]::text[]" if value else "null"
    value = (value or "").strip()
    if value == "":
        return "null"
    return "'" + value.replace("'", "''") + "'"


def main(folder, out):
    clubs = read(folder, "UCR_clubs_and_groups.csv")
    desc = {d["Organization ID"]: d for d in read(folder, "UCR_descriptions.csv")}

    rows = []
    for c in clubs:
        d = desc.get(c["Organization ID"], {})
        schedule = c["Meeting day and time reported"].strip()
        freq = c["Meeting frequency reported"].strip()
        if freq.startswith("Other (please write in the frequency)"):
            freq = freq.split(";", 1)[1].strip() if ";" in freq else ""
        if freq.startswith("Not applicable"):
            freq = ""
        rows.append("(" + ", ".join([
            c["Organization ID"], lit(c["Organization"]), lit(c["Organization type"]),
            lit([x.strip() for x in c["Categories"].split(";") if x.strip()]),
            "null" if schedule.lower() in NOT_LISTED else lit(schedule),
            lit(freq), lit(c["Meeting or practice notes from description"]),
            lit(d.get("Summary")), lit(d.get("Full description")),
            lit(c["Email"]), lit(c["Website"]), lit(c["Instagram"]), lit(c["Profile URL"]),
        ]) + ")")

    sql = SCHEMA + (
        "insert into public.clubs (id, name, organization_type, categories, meeting_schedule,\n"
        "  meeting_frequency, meeting_notes, summary, description, email, website, instagram, profile_url) values\n"
        + ",\n".join(rows) + ";\n")
    Path(out).write_text(sql, encoding="utf-8")
    print(f"Wrote {out}: {len(rows)} clubs")


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit(__doc__)
    main(sys.argv[1], sys.argv[2])
